package alphametics

import (
	"errors"
	"strings"
)

// Solve solves an alphametics puzzle of the form
// "WORD1 + WORD2 + ... == RESULT" and returns a mapping of each
// letter to a distinct digit such that the sum holds.
func Solve(puzzle string) (map[string]int, error) {
	parts := strings.Split(puzzle, " == ")
	if len(parts) != 2 {
		return nil, errors.New("puzzle must contain exactly one '=='")
	}
	addends := strings.FieldsFunc(parts[0], func(r rune) bool { return r == '+' })
	sums := strings.Fields(parts[1])
	if len(sums) != 1 {
		return nil, errors.New("puzzle must have a single result word")
	}

	words := append(append([]string{}, addends...), sums[0])

	// Collect letters in order of first appearance.
	var letters []string
	seen := make(map[rune]bool)
	for _, w := range words {
		for _, r := range w {
			if !seen[r] {
				seen[r] = true
				letters = append(letters, string(r))
			}
		}
	}
	if len(letters) > 10 {
		return nil, errors.New("puzzle has more than ten distinct letters")
	}

	// Leading letters of multi-character words cannot be zero.
	leading := make(map[rune]bool)
	for _, w := range words {
		if len(w) > 1 {
			leading[rune(w[0])] = true
		}
	}

	// Right-justified column access: the character of word w in column c
	// (counted from the right, 0 = units place), or 0 if the word is shorter.
	maxLen := 0
	for _, w := range words {
		if len(w) > maxLen {
			maxLen = len(w)
		}
	}
	colChar := func(w string, c int) (rune, bool) {
		i := len(w) - 1 - c
		if i < 0 {
			return 0, false
		}
		return rune(w[i]), true
	}
```

